mapper.select:
SELECT m.name AS member_name, COALESCE(deposits.total, 0) AS deposited_amount
LEFT JOIN ( SELECT dr.member_id, SUM(gt.amount) AS total FROM group_account ga JOIN group_transaction gt ON gt.account_id = ga.account_id JOIN saving_group_mock_deposit_request dr ON dr.transaction_id = gt.transaction_id AND dr.account_id = ga.account_id AND dr.status = 'COMPLETED' WHERE ga.group_id = #{groupId} AND gt.transaction_type = 'DEPOSIT' AND gt.transacted_at >= #{start} AND gt.transacted_at < #{end} GROUP BY dr.member_id ) deposits ON deposits.member_id = gm.member_id
ORDER BY gm.crew_member_id LIMIT #{size} OFFSET #{offset}

SELECT * FROM saving_group_turn_order_plan
WHERE saving_group_id = #{savingGroupId} AND effective_month <= #{month}
ORDER BY effective_month DESC LIMIT 1 FOR UPDATE

SELECT CAST(member_id AS CHAR) AS member_id, round_number AS sequence_number
FROM saving_group_turn_order_plan_member WHERE turn_order_plan_id = #{planId}
ORDER BY round_number FOR UPDATE

SELECT EXISTS(SELECT 1 FROM payout_request pr JOIN meeting_round mr ON mr.round_id = pr.round_id
    WHERE mr.group_id = #{groupId} AND mr.round_number >= #{startRound}
      AND pr.status IN ('PENDING', 'APPROVED', 'COMPLETED'))

mapper.sql:


        FROM payout_request req
        JOIN meeting_round mr ON mr.round_id = req.round_id
        JOIN members requester ON requester.member_id = req.requester_id
        WHERE mr.group_id = #{groupId}


        FROM expenses req
        JOIN members requester ON requester.member_id = req.applicant_id
        WHERE req.group_id = #{groupId}


AND requester.deleted_at IS NULL
AND EXISTS (SELECT 1 FROM group_member applicant_relation
            WHERE applicant_relation.group_id = #{groupId}
              AND applicant_relation.member_id = requester.member_id
              AND applicant_relation.membership_status = 'APPROVED')
AND req.status = #{status}

choose.otherwise:
UPDATE expenses SET status = #{status}, reviewer_id = #{reviewerId},
    reviewed_at = CURRENT_TIMESTAMP, reject_reason = #{rejectReason}
WHERE expense_id = #{requestId} AND group_id = #{groupId} AND status = 'PENDING'

