    AND (g.group_name LIKE #{keywordPattern} ESCAPE '!'
    OR g.description LIKE #{keywordPattern} ESCAPE '!')


    AND r.region_name = #{regionName}


AND r.province_name = #{provinceName}
AND r.district_name = #{districtName}
