mapper.select:
SELECT region_id
FROM region
WHERE region_name = #{regionName}

SELECT EXISTS(
SELECT 1 FROM members
WHERE member_id = #{memberId}
AND deleted_at IS NULL
)

mapper.update:
UPDATE saving_group
SET status = 'approved'
WHERE saving_group_id = #{savingGroupId}

mapper.select:
SELECT sg.saving_group_id, g.group_id, g.group_name, g.description,
sg.group_image AS group_image_path, r.region_name, g.max_members, sg.dues_amount, sg.dues_day, sg.status
ORDER BY g.created_at DESC, sg.saving_group_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT crew_member_id,
member_role,
membership_status
FROM group_member
WHERE group_id = #{groupId}
AND member_id = #{memberId}

mapper.sql:
SELECT crew_member_id, member_id, group_id, membership_status
FROM group_member
WHERE crew_member_id = #{crewMemberId}

mapper.update:
UPDATE group_member
SET membership_status = 'APPROVED',
    member_role = 'MEMBER',
    joined_at = CURRENT_TIMESTAMP,
    approved_at = CURRENT_TIMESTAMP,
    approved_by = #{approvedBy}
WHERE crew_member_id = #{crewMemberId}
  AND group_id = #{groupId}
  AND membership_status = 'PENDING'

UPDATE group_member
SET membership_status = 'REJECTED'
WHERE crew_member_id = #{crewMemberId}
  AND group_id = #{groupId}
  AND membership_status = 'PENDING'

UPDATE saving_group sg
JOIN `groups` g ON g.group_id = sg.group_id
SET sg.status = #{status}
WHERE sg.group_id = #{groupId}
AND g.deleted_at IS NULL

mapper.select:
SELECT group_id, COUNT(DISTINCT member_id) AS member_count FROM group_member WHERE membership_status = 'APPROVED' AND group_id IN
#{groupId}
GROUP BY group_id

mapper.update:
UPDATE group_notice
SET is_pinned = #{pinned}
WHERE group_id = #{groupId} AND notice_id = #{noticeId}
  AND deleted_at IS NULL
  AND is_pinned != #{pinned}

mapper.select:
SELECT DISTINCT member_role FROM group_member
WHERE group_id = #{groupId} AND member_id = #{memberId}
AND membership_status = 'APPROVED'

mapper.update:
UPDATE group_member
SET membership_status = 'LEFT',
left_at = CURRENT_TIMESTAMP
WHERE crew_member_id = #{crewMemberId}
AND group_id = #{groupId}
AND membership_status = 'APPROVED'

UPDATE group_member
SET membership_status = 'EXPELLED'
WHERE crew_member_id = #{crewMemberId}
AND group_id = #{groupId}
AND membership_status = 'APPROVED'

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM saving_group
    WHERE group_id = #{groupId}
      AND status IN ('02', '03')
)

mapper.sql:
FROM meeting_approval ma JOIN `groups` g ON g.group_id = ma.group_id JOIN saving_group sg ON sg.group_id = g.group_id JOIN members m ON m.member_id = g.member_id JOIN region r ON r.region_id = g.region_id WHERE 1 = 1 AND (g.deleted_at IS NULL OR ma.type = 'DELETE')
AND (ma.type = 'DELETE' OR m.deleted_at IS NULL)
AND ma.status = #{status}
AND ma.type = #{type}
AND g.group_name LIKE #{keywordPattern} ESCAPE '!'

mapper.select:
SELECT * FROM saving_group_mock_deposit_request
WHERE account_id = #{accountId} AND member_id = #{memberId} AND amount = #{amount}
  AND status = 'COMPLETED' AND window_anchor_request_id IS NULL
  AND completed_at > #{since}
ORDER BY completed_at DESC, deposit_request_id DESC LIMIT 1 FOR UPDATE

mapper.update:
UPDATE saving_group_mock_deposit_request
SET confirmation_token_hash = #{confirmationTokenHash}, confirmation_expires_at = #{confirmationExpiresAt}
WHERE deposit_request_id = #{depositRequestId} AND member_id = #{memberId}
  AND account_id = #{accountId} AND status = 'PENDING_CONFIRMATION'

mapper.select:
SELECT COUNT(*)
FROM group_event
WHERE group_id = #{groupId} AND event_date >= #{start} AND event_date < #{end}
